const blk=b=>{const k=BK[b[0]];return `<div class="blk" style="border-left:4px solid ${k[2]}"><p class="bh"><span>${k[0]} ${k[1]}</span><span class="tm">${b[1]}</span></p><p>${b[2]}</p>${b[3]!=="—"?`<p class="small">🎯 ${b[3]}</p>`:""}${b[4]?`<button class="primary" style="margin-top:8px" data-a="go:${b[4]}">Treino de hoje · Sessão ${b[4]}</button>`:""}</div>`};
const sch=()=>SCH[S.wk];
const PKEY="k1-natal-peso";
function medH(P,F){const n=v=>v==null||v===""?null:parseFloat(String(v).replace(",",".")),f1=v=>v==null?"—":v.toFixed(1).replace(".",","),dd=(a,b)=>a==null||b==null?"":`<span class="small" style="color:${a-b>0?"#f59e0b":a-b<0?"#22c55e":"#9aa"}"> ${a-b>=0?"+":""}${f1(a-b)}</span>`;
const C=[["kg","Peso"]].concat(F);if(!P.length)return"";const first=c=>{for(let i=P.length-1;i>=0;i--){const v=n(P[i][c]);if(v!=null)return v}return null};
const prev=(i,c)=>{for(let k=i+1;k<P.length;k++){const v=n(P[k][c]);if(v!=null)return v}return null};
const spark=c=>{const v=P.slice(0,12).map(x=>n(x[c])).filter(x=>x!=null).reverse();if(v.length<2)return"";const lo=Math.min(...v),hi=Math.max(...v),r=hi-lo||1;return `<div class="small" style="display:flex;align-items:center;gap:6px;margin:2px 0"><span style="width:90px">${C.find(x=>x[0]===c)[1]}</span><svg width="140" height="28" viewBox="0 0 140 28"><polyline fill="none" stroke="#f472b6" stroke-width="2" points="${v.map((y,i)=>`${(i*136/(v.length-1)+2).toFixed(1)},${(26-(y-lo)/r*24).toFixed(1)}`).join(" ")}"/></svg><span>${f1(v[0])}→${f1(v[v.length-1])}</span></div>`};
let t=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><tr>${["Data"].concat(C.map(c=>c[1])).map(h=>`<th style="text-align:left;padding:4px;border-bottom:1px solid #333">${h}</th>`).join("")}<th></th></tr>`+
P.slice(0,12).map((x,i)=>`<tr><td style="padding:4px">${esc(x.d).slice(5)}</td>${C.map(([c])=>{const v=n(x[c]);return `<td style="padding:4px">${f1(v)}${dd(v,prev(i,c))}</td>`}).join("")}<td><button class="del" data-a="pdel:${i}">×</button></td></tr>`).join("")+`</table></div>`;
t+=`<p class="small">Cor = variação face à medição anterior. Desde a 1.ª: ${C.map(([c,h])=>{const a=n(P[0][c]),b=first(c);return a!=null&&b!=null?`${h} ${a-b>=0?"+":""}${f1(a-b)}`:null}).filter(Boolean).join(" · ")||"—"}</p>`+C.map(([c])=>spark(c)).join("");return t}
function medD(P,c){const n=v=>v==null||v===""?null:parseFloat(String(v).replace(",","."));const a=P.findIndex(x=>n(x[c])!=null);if(a<0)return null;for(let k=a+1;k<P.length;k++){const v=n(P[k][c]);if(v!=null){return{d:n(P[a][c])-v,kg:n(P[a].kg)-n(P[k].kg)}}}return null}
function pesoV(){const P=JSON.parse(localStorage.getItem(PKEY)||"[]"),n=v=>parseFloat(String(v).replace(",","."));let st="";
if(P.length>=2){const r=(a,b)=>((n(a.kg)-n(b.kg))/Math.max(1,(new Date(a.d)-new Date(b.d))/6048e5));const r1=r(P[0],P[1]),r2=P.length>=3?r(P[1],P[2]):null;
st=`<p>Ritmo atual: <b>${r1>=0?"+":""}${r1.toFixed(2)} kg/semana</b></p>`+(r1>0.35&&r2!==null&&r2>0.35?'<p class="warn">⚠️ &gt;0,35 kg/semana 2 semanas seguidas → tirar 30 g de hidratos/dia.</p>':r2!==null&&Math.abs(r1)<0.05&&Math.abs(r2)<0.05?'<p class="warn">Peso parado 2 semanas → se a força não sobe, somar 25 g de hidratos/dia.</p>':r1<=0.25&&r1>=0?'<p>✅ Dentro do alvo.</p>':"")}
return card("Pesagem semanal",`<p>Mesmo dia da semana, de manhã, em jejum, depois da casa de banho. Alvo: ganhar ≤0,25 kg/semana.</p><p class="small">Regras: &gt;0,35 kg/semana durante 2 semanas → −30 g hidratos/dia. Peso parado 2 semanas e força sem subir → +25 g hidratos/dia.</p><div class="form"><label>Data<input id="pd" type="date" value="${hoje}"></label><label>Peso (kg)<input id="pk" type="number" inputmode="decimal"></label><label>Perímetro abdominal (cm)<input id="pab" type="number" inputmode="decimal" step="0.1" placeholder="opcional"></label><label>Perímetro dorsal (cm)<input id="pdo" type="number" inputmode="decimal" step="0.1" placeholder="opcional"></label><p class="small"><b>Como medir:</b> mesmo dia e hora da pesagem, em jejum; fita justa sem apertar a pele, paralela ao chão. <b>Abdominal:</b> à altura do umbigo, barriga relaxada, no fim de expirar. <b>Dorsal:</b> peito/costas no ponto mais largo dos dorsais, logo abaixo das axilas, braços relaxados, respiração normal.</p><button class="primary" data-a="psave">Guardar pesagem</button><p class="small">Fica só neste aparelho.</p></div>${st}${(()=>{const a=medD(P,"ab"),o=medD(P,"do");let m="";if(a&&a.kg>0.2){m+=a.d<=0.5*a.kg+0.1?"<p>✅ Peso a subir com abdominal estável → provável ganho de massa magra.</p>":"<p class=\"warn\">⚠️ Abdominal a subir mais depressa que o peso (&gt;0,5 cm por kg) → gordura a mais: tirar 30 g de hidratos/dia (regra acima).</p>"}else if(a&&a.d>0.5)m+="<p class=\"warn\">⚠️ Abdominal a subir sem o peso subir → rever hidratos/gordura.</p>";if(o&&o.d>0)m+="<p>💪 Dorsal a subir → bom sinal (costas a crescer).</p>";return m})()}${medH(P,[["ab","Abdom."],["do","Dorsal"]])}`)}
const KEY="k1-natal-registo";
